cd /tmp/epafiles && for yr in {2000..2010}; do
  csv=daily_42101_${yr}.csv
  if [ -f "$csv" ]; then
    echo "Year $yr: processing"
    # awk with proper quoting
    awk -F',' 'BEGIN{OFS=FS}
    NR>1{
      gsub(/"/,"",$0);
      # rebuild fields by splitting line using comma - but fields may be quoted; however EPA CSV seems simple
      split($0,cols,",")
      cbsa=cols[1]; date=cols[3]; aqi=cols[8];
      key=cbsa"|"date;
      if(aqi=="" || aqi=="AQI") next;
      if(aqi+0>max[key]+0) max[key]=aqi+0
    }
    END{
      for(k in max){ split(k,arr,"|"); cbsa=arr[1]; date=arr[2]; if(max[k]>50) print cbsa","date","max="max[k]}
    }' "$csv" > co_exceed_${yr}.csv
  fi
done

echo "Done"

python3 - << 'PY'
import csv,os
path='/tmp/epafiles'
cbsa_list=['Portland-Vancouver-Hillsboro, OR-WA','Wichita, KS','San Diego-Carlsbad, CA']
results={}
for yr in range(2000,2011):
    fn=os.path.join(path,f'daily_42101_{yr}.csv')
    if not os.path.exists(fn):
        print('MISSING',fn)
        continue
    # map cbsa -> date->maxAQI
    per={cb:{} for cb in cbsa_list}
    with open(fn,'r',newline='') as f:
        reader=csv.DictReader(f)
        for row in reader:
            cb=row.get('CBSA Name','').strip()
            if cb in per:
                date=row.get('Date Local')
                aqi=row.get('AQI')
                try:
                    aqi_val=int(aqi)
                except:
                    continue
                prev=per[cb].get(date)
                if prev is None or aqi_val>prev:
                    per[cb][date]=aqi_val
    # Now evaluate whether for every day of the year the cbsa had maxAQI <=50
    import datetime
    ok_all=True
    reasons={}
    for cb in cbsa_list:
        # build date range
        start=datetime.date(yr,1,1)
        end=datetime.date(yr,12,31)
        delta=datetime.timedelta(days=1)
        d=start
        ok=True
        missing_dates=[]
        exceed_dates=[]
        while d<=end:
            s=d.isoformat()
            if s not in per[cb]:
                missing_dates.append(s)
                ok=False
            else:
                if per[cb][s]>50:
                    exceed_dates.append((s,per[cb][s]))
                    ok=False
            d+=delta
        results.setdefault(yr,{})[cb]={'ok':ok,'missing':missing_dates[:3],'exceed_count':len(exceed_dates),'exceed_dates':exceed_dates[:3]}
        if not ok:
            ok_all=False
    results[yr]['all_ok']=ok_all
# print summary years where all three OK
oks=[str(yr) for yr in range(2000,2011) if results.get(yr,{}).get('all_ok')]
print('Years where all three all_ok:',','.join(oks))
# print details
for yr in range(2000,2011):
    print(yr, results.get(yr))
PY
